package org.transittr;
import java.io.*;import java.util.*;import org.json.*;
/** ESHOT's anonymous transport API: durationToTarget is seconds for the requested stop. */
public final class EshotClient {
 private static final String BASE="https://appapi.eshot.gov.tr/api/Transportation";private static String token="";private static long expires;
 private static synchronized String token()throws IOException{if(token.length()>0&&System.currentTimeMillis()<expires)return token;try{JSONObject body=new JSONObject();body.put("userName","tur");body.put("password","t@r!");JSONObject response=new JSONObject(ApiHttp.json(BASE+"/Login",body));if(response.getJSONObject("error").optInt("code",-1)!=0)throw new IOException("ESHOT anonim erişimi alınamadı");token=response.getJSONObject("data").getString("Item1");expires=System.currentTimeMillis()+30*60000L;return token;}catch(JSONException e){throw new IOException("ESHOT erişim yanıtı okunamadı");}}
 public static JSONObject get(String path)throws IOException{for(int attempt=0;attempt<2;attempt++){Map<String,String> headers=new HashMap<String,String>();headers.put("Authorization","bearer "+token());try{return new JSONObject(ApiHttp.text(BASE+path,null,null,headers,4194304));}catch(JSONException e){throw new IOException("ESHOT yanıtı okunamadı");}catch(IOException e){if(attempt==0&&e.getMessage()!=null&&e.getMessage().indexOf("401")>=0){synchronized(EshotClient.class){token="";}continue;}throw e;}}throw new IOException("ESHOT erişimi yenilenemedi");}
 public static JourneyData.Snapshot query(String stop,String filter)throws IOException{try{JSONObject root=get("/getVehiclesByStationCode/"+stop);if(root.getJSONObject("error").optInt("code",-1)!=0)throw new IOException("ESHOT varış servisi hata verdi");return parse(root.getJSONArray("data"),stop,filter);}catch(JSONException e){throw new IOException("ESHOT araçları okunamadı");}}
 public static JourneyData.Snapshot parse(JSONArray rows,String stop,String filter)throws JSONException,IOException{if(rows.length()>200)throw new IOException("ESHOT araç sınırı");JourneyData.Snapshot s=new JourneyData.Snapshot();s.source="ESHOT Mobil · hedef durağa süre";
  for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String line=SourceTools.text(r,"lineCode");if(!SourceTools.matches(line,filter))continue;JourneyData.Vehicle v=new JourneyData.Vehicle();v.id="eshot:"+r.optString("vehicleNo");v.line=line;v.name=r.optString("routeName",r.optString("lineName",""));v.routeCode=r.optString("routeId");JSONObject p=r.optJSONObject("currentLocation");if(p!=null){v.lat=SourceTools.number(p,"lat");v.lon=SourceTools.number(p,"lng");}v.sourceTime=r.optString("gpsTime","");v.observedAt=SourceTools.time(v.sourceTime);long seconds=r.isNull("durationToTarget")?-1:r.optLong("durationToTarget",-1);String target=r.optString("targetStationId",stop);v.etaSeconds=stop.equals(target)&&seconds>=0&&seconds<86400?seconds:-1;v.eta=SourceTools.minutes(v.etaSeconds);v.arrivalStop=stop;v.etaIsStopArrival=v.etaSeconds>=0;s.rows.add(v);}
  SourceTools.sort(s);if(s.rows.isEmpty())s.message="Bu durak ve hat için yaklaşan araç yok.";return s;
 }
}
